@pytest.mark.parametrize("tokens", [4095, 4096, 4097]) @pytest.mark.parametrize("kind", ["random", "mixed_maxima", "zero_q", "zero_v", "tiny_v", "subnormal_v"]) @torch.inference_mode() def test_long_exact_stream_matches_dense(tokens, kind): q, k, v = inputs(tokens, seed=153) if kind == "mixed_maxima": # Different Q rows see different sequences of maxima and identity scales. q[:, ::2].mul_(3) q[:, 1::4].zero_() k[:, 64::128].mul_(3) elif kind == "zero_q": q.zero_() elif kind == "zero_v": v.zero_() elif kind == "tiny_v": v.mul_(2.0**-120) elif kind == "subnormal_v": v.mul_(2.0**-130) mask = torch.ones((tokens + 63) // 64, device="cuda", dtype=torch.bool) actual = sol_attn(q, k, v, exact_block_mask=mask) expected = torch.nn.functional.scaled_dot_product_attention( q.float().transpose(1, 2), k.float().transpose(1, 2), v.float().transpose(1, 2), ).transpose(1, 2) assert torch.isfinite(actual).all() if kind in ("tiny_v", "subnormal_v"): # Scale the comparison, not the input to the kernel: a normal absolute # tolerance would accept an accidentally all-zero tiny result. scale = 2.0**(120 if kind == "tiny_v" else 130) > torch.testing.assert_close(actual.double() * scale, expected.double() * scale, atol=0.02, rtol=0.02) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 444927 / 1048320 (42.4%) E Greatest absolute difference: 0.06261634826660156 at index (0, 419, 0, 47) (up to 0.02 allowed) E Greatest relative difference: 1.0037300883602898 at index (0, 419, 0, 47) (up to 0.02 allowed)
